/**
 * Vitest setup file for DUCK-E frontend tests.
 *
 * This file runs before each test file and sets up the testing environment.
 */

import { vi } from 'vitest';

// Mock WebRTC and audio APIs that don't exist in jsdom
global.MediaStream = vi.fn().mockImplementation(() => ({
  getTracks: () => [],
  getAudioTracks: () => [],
  getVideoTracks: () => [],
}));

global.MediaRecorder = vi.fn().mockImplementation(() => ({
  start: vi.fn(),
  stop: vi.fn(),
  pause: vi.fn(),
  resume: vi.fn(),
  ondataavailable: null,
  onstop: null,
  state: 'inactive',
}));

// Mock AudioContext
global.AudioContext = vi.fn().mockImplementation(() => ({
  state: 'running',
  suspend: vi.fn().mockResolvedValue(undefined),
  resume: vi.fn().mockResolvedValue(undefined),
  close: vi.fn().mockResolvedValue(undefined),
  createMediaStreamSource: vi.fn().mockReturnValue({
    connect: vi.fn(),
    disconnect: vi.fn(),
  }),
  createGain: vi.fn().mockReturnValue({
    connect: vi.fn(),
    gain: { value: 1 },
  }),
  destination: {},
}));

// Mock getUserMedia
global.navigator.mediaDevices = {
  getUserMedia: vi.fn().mockResolvedValue(new MediaStream()),
  enumerateDevices: vi.fn().mockResolvedValue([]),
};

// Mock WebSocket
global.WebSocket = vi.fn().mockImplementation((url) => ({
  url,
  readyState: 1, // OPEN
  send: vi.fn(),
  close: vi.fn(),
  addEventListener: vi.fn(),
  removeEventListener: vi.fn(),
  onopen: null,
  onclose: null,
  onmessage: null,
  onerror: null,
  CONNECTING: 0,
  OPEN: 1,
  CLOSING: 2,
  CLOSED: 3,
}));

// Mock localStorage
const localStorageMock = {
  store: {},
  getItem: vi.fn((key) => localStorageMock.store[key] || null),
  setItem: vi.fn((key, value) => {
    localStorageMock.store[key] = String(value);
  }),
  removeItem: vi.fn((key) => {
    delete localStorageMock.store[key];
  }),
  clear: vi.fn(() => {
    localStorageMock.store = {};
  }),
};
global.localStorage = localStorageMock;

// Reset mocks before each test
beforeEach(() => {
  vi.clearAllMocks();
  localStorageMock.clear();
  document.body.innerHTML = '';
});

// Mock ag2client (the WebRTC library DUCK-E uses)
global.ag2client = {
  WebRTC: vi.fn().mockImplementation((socketUrl) => ({
    socketUrl,
    connect: vi.fn().mockResolvedValue(undefined),
    close: vi.fn(),
    send: vi.fn(),
    onDisconnect: null,
    onMessage: null,
    audioContext: new AudioContext(),
  })),
};

// Helper to create DOM elements for testing
global.createTestDOM = () => {
  document.body.innerHTML = `
    <div id="connection-status">
      <span id="status-text">Ready to Connect</span>
    </div>
    <button id="connect-button">
      <span class="button-text">Connect</span>
    </button>
    <div id="transcript-container">
      <div id="transcript-content"></div>
    </div>
    <button id="toggle-audio">
      <span id="audio-icon">🔊</span>
    </button>
  `;
};

console.log('DUCK-E frontend test setup complete');

"""
Pytest configuration and fixtures for authentication tests
"""
import pytest
from datetime import datetime, timedelta, timezone
from jose import jwt
from typing import Dict, Any


# Test JWT configuration
TEST_SECRET_KEY = "test-secret-key-for-jwt-validation-only"  # pragma: allowlist secret
TEST_ALGORITHM = "HS256"


@pytest.fixture
def jwt_secret():
    """JWT secret key for testing"""
    return TEST_SECRET_KEY


@pytest.fixture
def jwt_algorithm():
    """JWT algorithm for testing"""
    return TEST_ALGORITHM


@pytest.fixture
def create_test_token():
    """Factory fixture for creating test JWT tokens"""
    def _create_token(payload: Dict[str, Any], secret: str = TEST_SECRET_KEY) -> str:
        """Create a test JWT token with given payload"""
        # Add expiration if not present
        if "exp" not in payload:
            payload["exp"] = datetime.now(timezone.utc) + timedelta(hours=2)

        return jwt.encode(payload, secret, algorithm=TEST_ALGORITHM)

    return _create_token


@pytest.fixture
def valid_premium_token(create_test_token):
    """Valid premium tier JWT token"""
    payload = {
        "sub": "test_premium_user",
        "tier": "premium",
        "exp": datetime.now(timezone.utc) + timedelta(hours=2)
    }
    return create_test_token(payload)


@pytest.fixture
def valid_enterprise_token(create_test_token):
    """Valid enterprise tier JWT token"""
    payload = {
        "sub": "test_enterprise_user",
        "tier": "enterprise",
        "exp": datetime.now(timezone.utc) + timedelta(hours=8)
    }
    return create_test_token(payload)


@pytest.fixture
def expired_token(create_test_token):
    """Expired JWT token"""
    payload = {
        "sub": "expired_user",
        "tier": "premium",
        "exp": datetime.now(timezone.utc) - timedelta(hours=1)
    }
    return create_test_token(payload)


@pytest.fixture
def token_with_invalid_signature():
    """Token with invalid signature (signed with wrong key)"""
    payload = {
        "sub": "attacker",
        "tier": "enterprise",
        "exp": datetime.now(timezone.utc) + timedelta(hours=1)
    }
    wrong_secret = "wrong-secret-key"  # pragma: allowlist secret
    return jwt.encode(payload, wrong_secret, algorithm=TEST_ALGORITHM)


@pytest.fixture
def mock_redis_client():
    """Mock Redis client for testing token revocation"""
    from unittest.mock import AsyncMock, Mock

    mock = Mock()
    mock.get = AsyncMock(return_value=None)
    mock.set = AsyncMock(return_value=True)
    mock.setex = AsyncMock(return_value=True)
    mock.delete = AsyncMock(return_value=1)

    return mock
